import csv

# Read system inventory
with open('data/current_system_inventory.csv', 'r') as f:
    reader = csv.DictReader(f)
    systems = list(reader)

print(f"Total systems: {len(systems)}")

# By status
status_counts = {}
for s in systems:
    st = s['status']
    status_counts[st] = status_counts.get(st, 0) + 1

print("\nBy status:")
for st, count in sorted(status_counts.items()):
    print(f"  {st}: {count}")

# By integration type
integration_counts = {}
for s in systems:
    it = s['integration_type']
    integration_counts[it] = integration_counts.get(it, 0) + 1

print("\nBy integration type:")
for it, count in sorted(integration_counts.items()):
    print(f"  {it}: {count}")

# Total data volume
total_data = sum(float(s['data_volume_gb']) for s in systems)
print(f"\nTotal data volume: {total_data:.0f} GB ({total_data/1024:.1f} TB)")

# Active systems by owner
print("\nActive systems by owner:")
active_by_owner = {}
for s in systems:
    if s['status'] == 'active':
        owner = s['owner_dept']
        active_by_owner[owner] = active_by_owner.get(owner, 0) + 1
for owner, count in sorted(active_by_owner.items()):
    print(f"  {owner}: {count}")

# Planned systems
print("\nPlanned systems:")
for s in systems:
    if s['status'] == 'planned':
        print(f"  {s['system_name']} - {s['owner_dept']}")

# Deprecated systems
print("\nDeprecated systems:")
for s in systems:
    if s['status'] == 'deprecated':
        print(f"  {s['system_name']} - deployed {s['deploy_date']}")
EOF
